# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import random
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast via best-of-many Steiner trees: build candidate trees by
    attaching destinations in several priority orders (plus a globally
    cheapest-attachment SPH tree and the union of per-dst shortest paths),
    score each candidate by max(unique edge-cost sum, per-dst path-cost sum)
    so shared trunk edges are rewarded while per-dst costs stay bounded,
    and reuse the winning tree's per-dst edge lists across all partitions
    to avoid redundant transfers."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    dist_cache = {}

    def sp_from(node):
        if node not in dist_cache:
            dist, paths = nx.single_source_dijkstra(h, node, weight="cost")
            dist_cache[node] = (dist, paths)
        return dist_cache[node]

    def edge_cost(s, t):
        c = G[s][t].get("cost")
        return 0.0 if c is None else float(c)

    def add_path(tree, tree_nodes, path):
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            if not tree.has_edge(s, t):
                tree.add_edge(s, t, cost=edge_cost(s, t), data=G[s][t])
            tree_nodes.update([s, t])

    def attach(dst, tree_nodes, tree):
        """Attach dst via the cheapest path from any node already in tree."""
        best = None
        for node in tree_nodes:
            dist, paths = sp_from(node)
            if dst in dist and (best is None or dist[dst] < best[0]):
                best = (dist[dst], paths[dst])
        if best is None:
            return False  # dst unreachable from the current tree
        add_path(tree, tree_nodes, best[1])
        return True

    def build_tree(order):
        """Greedy Steiner: attach dsts sequentially in the given order."""
        tree_nodes = {src}
        tree = nx.DiGraph()
        done = set()
        for dst in order:
            if dst in dsts and dst not in done and attach(dst, tree_nodes, tree):
                done.add(dst)
        for dst in dsts:  # catch any dsts the ordering missed
            if dst not in done:
                attach(dst, tree_nodes, tree)
        return tree

    def build_greedy_tree():
        """Classic shortest-path heuristic: globally cheapest attachment."""
        tree_nodes = {src}
        tree = nx.DiGraph()
        remaining = set(dsts)
        while remaining:
            best = None
            for dst in remaining:
                for node in tree_nodes:
                    dist, paths = sp_from(node)
                    if dst in dist and (best is None or dist[dst] < best[0]):
                        best = (dist[dst], dst, paths[dst])
            if best is None:
                remaining.pop()
                continue
            _, dst, path = best
            add_path(tree, tree_nodes, path)
            remaining.discard(dst)
        return tree

    def tree_scores(tree):
        """Return (unique_edge_sum, path_sum); None if a dst is unreachable."""
        try:
            dist = nx.single_source_dijkstra_path_length(tree, src, weight="cost")
        except Exception:
            return None
        path_sum = 0.0
        for dst in dsts:
            if dst not in dist:
                return None
            path_sum += dist[dst]
        unique_sum = sum(edge_cost(s, t) for s, t in tree.edges())
        return unique_sum, path_sum

    # candidate attachment orders: natural, sorted, reversed, near/far-first
    direct_dist, direct_paths = sp_from(src)
    orders = [
        list(dsts),
        sorted(dsts),
        sorted(dsts, reverse=True),
        sorted(dsts, key=lambda d: direct_dist.get(d, float("inf"))),
        sorted(dsts, key=lambda d: direct_dist.get(d, float("-inf")), reverse=True),
    ]
    rnd = random.Random(1234)
    for _ in range(6):  # seeded random restarts for extra diversity
        o = list(dsts)
        rnd.shuffle(o)
        orders.append(o)

    candidates = [build_tree(o) for o in orders]
    candidates.append(build_greedy_tree())
    # union of per-dst shortest paths: optimal if edges are not deduplicated
    union_tree = nx.DiGraph()
    union_nodes = {src}
    for dst in dsts:
        if dst in direct_dist:
            add_path(union_tree, union_nodes, direct_paths[dst])
    candidates.append(union_tree)

    best_tree, best_key = None, None
    for tree in candidates:
        scores = tree_scores(tree)
        if scores is None:
            continue
        # hedge: worst-case of dedup cost (unique edges) vs no-dedup cost
        key = (max(scores), scores[0])
        if best_key is None or key < best_key:
            best_tree, best_key = tree, key
    if best_tree is None:
        best_tree = build_greedy_tree()

    # Extract each dst's cheapest path within the winning tree
    for dst in dsts:
        try:
            path = nx.shortest_path(best_tree, src, dst, weight="cost")
        except Exception:
            path = nx.dijkstra_path(h, src, dst, weight="cost")
        edge_list = []
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            data = G[s][t] if G.has_edge(s, t) else best_tree[s][t].get("data", {})
            edge_list.append([s, t, data])
        # reuse the same edge list for all partitions (no redundant transfers)
        for j in range(bc_topology.num_partitions):
            bc_topology.set_dst_partition_paths(dst, j, list(edge_list))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


